const updateAccountStats = `-- name: UpdateAccountStats :exec
UPDATE account_stats SET
    statuses_count = statuses_count + $2,
    following_count = following_count + $3,
    followers_count = followers_count + $4,
    last_status_at = COALESCE($5, last_status_at),
    updated_at = now()
WHERE account_id = $1
`

type UpdateAccountStatsParams struct {
	AccountID      int64              `db:"account_id" json:"account_id"`
	StatusesDelta  int64              `db:"statuses_delta" json:"statuses_delta"`
	FollowingDelta int64              `db:"following_delta" json:"following_delta"`
	FollowersDelta int64              `db:"followers_delta" json:"followers_delta"`
	LastStatusAt   pgtype.Timestamptz `db:"last_status_at" json:"last_status_at"`
}

func (q *Queries) UpdateAccountStats(ctx context.Context, arg UpdateAccountStatsParams) error {
	_, err := q.db.Exec(ctx, updateAccountStats,
		arg.AccountID,
		arg.StatusesDelta,
		arg.FollowingDelta,
		arg.FollowersDelta,
		arg.LastStatusAt,
	)
	return err
}
